//
//  CollectionRecommendation.swift
//  ChewSenseLive
//
//  Types for the closed-loop "what should I record next?" plan generated by
//  the Python retraining pipeline and bundled into the app during deploy.
//

import Foundation

struct CollectionPlan: Equatable {
    let version: Int
    let modelID: String
    let datasetHash: String
    let generatedAt: String
    let sourceSplit: String
    let recommendations: [CollectionRecommendation]

    var hasRecommendations: Bool {
        !recommendations.isEmpty
    }
}

struct CollectionRecommendation: Identifiable, Equatable {
    let id: String
    let activity: String
    let activityLabel: String
    let expectedLabelClass: String
    let priority: Int
    let requestedMinutes: Int
    let reasonCodes: [String]
    let reason: String
    let currentMinutes: Double
    let targetMinutes: Double

    var activityPreset: ActivityPreset? {
        ActivityPreset.preset(forActivitySlug: activity)
    }

    var priorityLabel: String {
        "P\(priority)"
    }

    var minutesLabel: String {
        "\(requestedMinutes) min"
    }

    var scenarioText: String {
        "\(activityLabel), \(requestedMinutes) min. \(reason)"
    }
}
